"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from gpu_bnb.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_search_ranks_and_quotes(self):
        out = self.run_cli(
            [
                "search",
                str(EX / "listings.json"),
                "--start",
                "2026-11-01T01:00",
                "--end",
                "2026-11-01T04:00",
                "--min-vram",
                "48",
            ]
        )
        self.assertEqual([r["gpu"] for r in out], ["H100"])
        self.assertEqual(out[0]["host_amount"], 9.0)

    def test_outside_host_windows_is_excluded(self):
        out = self.run_cli(
            [
                "search",
                str(EX / "listings.json"),
                "--start",
                "2026-11-01T10:00",
                "--end",
                "2026-11-01T12:00",
                "--gpu",
                "4090",
            ]
        )
        self.assertEqual(out, [])


if __name__ == "__main__":
    unittest.main()
